def slice_normal(self):
    """Return unit normal to the planes, pointing along increasing slice index

    The normal from the cross product of the *ImageOrientationPatient*
    direction cosines (see ``Wrapper.slice_normal``) defines the plane
    normal, but not which way the third axis of the data block runs along
    it.  That depends on the ordering of the frames (see ``frame_order``),
    so we take the direction from the *ImagePositionPatient* of the frames
    giving the planes of the data block.  Without this, the affine can
    describe planes in the reverse order to the data.
    """
    normal = super().slice_normal
    if normal is None:
        return None
    positions = self._slice_frame_positions
    if positions is None or len(positions) < 2:
        # A single plane, or no per-frame positions: nothing to tell us
        # which way round the planes are.
        return normal
    # Distance travelled along the normal from the first to the last plane
    travel = float(np.dot(positions[-1] - positions[0], normal))
    if travel < -self._slice_travel_tol:
        # The planes of the data block run against the normal
        return -normal
    return normal

